function matches(pattern: Pattern, url: string): boolean {
  const rewrite = typeof pattern === 'string' ? { source: pattern, function: 'f' } : { regex: pattern.regex, function: 'f' };
  return rewriteTarget(hostingRewrites({ hosting: { rewrites: [rewrite] } }), hostingPathname(url)) !== null;
}

describe('rewrite matching agrees with superstatic', () => {
  test('every row of the differential table', () => {
    const disagreements = SUPERSTATIC
      .filter(([pattern, url, expected]) => matches(pattern, url) !== expected)
      .map(([pattern, url, expected]) => `${JSON.stringify(pattern)} ${url}: superstatic ${expected}`);
    expect(disagreements).toEqual([]);
  });
});

describe('hostingRewrites', () => {
  const rewrites = hostingRewrites({
    hosting: {
      public: 'public',
      rewrites: [
        { source: '/api/**', function: 'api' },
        { source: '/east/**', function: { functionId: 'east', region: 'us-east1' } },
        { source: '/legacy/**', function: 'legacy', region: 'europe-west1' },
        { regex: '^/rx/\\d+$', function: 'byRegex' },
        { source: '**', destination: '/index.html' },
        { source: '/late/**', function: 'unreachable' },
      ],
    },
  });

  test('reads every function destination form, with no region when the rewrite names none', () => {
    expect(rewriteTarget(rewrites, '/api/items')).toEqual({ functionId: 'api', region: null });
    expect(rewriteTarget(rewrites, '/east/x')).toEqual({ functionId: 'east', region: 'us-east1' });
    expect(rewriteTarget(rewrites, '/legacy/x')).toEqual({ functionId: 'legacy', region: 'europe-west1' });
    expect(rewriteTarget(rewrites, '/rx/12')).toEqual({ functionId: 'byRegex', region: null });
  });

  test('the first matching rewrite wins, so a function after a ** destination is never reached', () => {
    expect(rewriteTarget(rewrites, '/late/x')).toBeNull();
    expect(rewriteTarget(rewrites, '/page')).toBeNull();
  });

  test('a rewrite that does not compile is skipped with a warning; the others still apply', () => {
    const warnings: string[] = [];
    const parsed = hostingRewrites({
      hosting: { rewrites: [{ regex: '(', function: 'broken' }, { source: '/api{,/**}', function: 'api' }] },
    }, (warning) => warnings.push(warning));
    expect(warnings).toHaveLength(1);
    expect(warnings[0]).toContain('hosting.rewrites[0]');
    expect(rewriteTarget(parsed, '/api/x')).toEqual({ functionId: 'api', region: null });
  });

  test('a multi-site array uses the first site, and no hosting config has no rewrites', () => {
    expect(hostingRewrites({ hosting: [{ rewrites: [{ source: '/a', function: 'a' }] }, { rewrites: [] }] })).toHaveLength(1);
    expect(hostingRewrites({})).toEqual([]);
    expect(hostingRewrites(null)).toEqual([]);
  });
});

describe('hostingPathname', () => {
  test('drops the query and fragment, keeps percent-encoding, and resolves dot segments', () => {
    expect(hostingPathname('/api/x?q=1#f')).toBe('/api/x');
    expect(hostingPathname('/api/caf%C3%A9')).toBe('/api/caf%C3%A9');
    expect(hostingPathname('/x/../api/x')).toBe('/api/x');
    expect(hostingPathname('/api//x/')).toBe('/api/x/');
  });
});

describe('sessionCookieOnly', () => {
  test('keeps only __session', () => {
    expect(sessionCookieOnly('a=1; __session=abc; b=2')).toBe('__session=abc');
    expect(sessionCookieOnly('a=1; b=2')).toBeUndefined();
    expect(sessionCookieOnly(undefined)).toBeUndefined();
  });
});
